code.C:
#include <stdio.h>
int main() {
    long long facts[] = {1, 1, 2, 6, 24, 120, 720, 5040, 40320, 362880};
    char s[1005]; if (scanf("%s", s) != 1) return 0;
    long long sum = 0;
    for (int i = 0; s[i]; i++) sum += facts[s[i] - '0'];
    printf("%lld\n", sum);
    return 0;
}

code.C++:
#include <iostream>
#include <string>
using namespace std;
int main() {
    long long facts[] = {1, 1, 2, 6, 24, 120, 720, 5040, 40320, 362880};
    string s; if (!(cin >> s)) return 0;
    long long sum = 0;
    for (char c : s) sum += facts[c - '0'];
    cout << sum << "\n";
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        long[] facts = {1, 1, 2, 6, 24, 120, 720, 5040, 40320, 362880};
        Scanner sc = new Scanner(System.in);
        if (sc.hasNext()) {
            String s = sc.next();
            long sum = 0;
            for (char c : s.toCharArray()) sum += facts[c - '0'];
            System.out.println(sum);
        }
    }
}

